11	// AscendC RMSNorm kernel — merged strategies: merge_n, single_row, splitd
12	// Supports float32, float16, bfloat16
13	// Format: Abs-style with dtype dispatch in __global__ entry
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 1;
18	
19	// ---------------------------------------------------------------------------
20	// Inline helpers
21	// ---------------------------------------------------------------------------
22	
23	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
24	{
25	    if (b == 0U) { return 0U; }
26	    return (a + b - 1U) / b;
27	}
28	
29	template <typename T>
30	__aicore__ inline void LoadGmToUb(
31	    AscendC::LocalTensor<T> &dst,
32	    AscendC::GlobalTensor<T> src,
33	    uint32_t count)
34	{
35	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
36	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
37	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
38	}
39	
40	template <typename T>
41	__aicore__ inline void StoreUbToGm(
42	    AscendC::GlobalTensor<T> dst,
43	    AscendC::LocalTensor<T> &src,
44	    uint32_t count)
45	{
46	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
47	    AscendC::DataCopyPad(dst, src, copyParams);
48	}
49	
50	// =========================================================================
51	// Strategy-agnostic helper functions
52	// =========================================================================
53	
54	__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
55	{
56	    if (blockM == 0) { return 0; }
57	    return (M + blockM - 1) / blockM;
58	}
59	
60	template <typename T>
61	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
62	{
63	    if constexpr (std::is_same_v<T, bfloat16_t>) {
64	        return AscendC::RoundMode::CAST_ROUND;
65	    }
66	    return AscendC::RoundMode::CAST_NONE;
67	}
68	
69	template <typename T>
70	__aicore__ inline void PrepareInputTensorHelper(
71	    AscendC::LocalTensor<float> &dst,
72	    AscendC::LocalTensor<T> &src,
73	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
74	    int32_t count)
75	{
76	    if constexpr (std::is_same_v<T, float>) {
77	        dst = src.template ReinterpretCast<float>();
78	    } else {
79	        dst = castBuf.Get<float>();
80	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
81	        AscendC::PipeBarrier<PIPE_V>();
82	    }
83	}
84	
85	template <typename T>
86	__aicore__ inline void PrepareOutputTensorHelper(
87	    AscendC::LocalTensor<float> &dst,
88	    AscendC::LocalTensor<T> &out,
89	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
90	{
91	    if constexpr (std::is_same_v<T, float>) {
92	        dst = out.template ReinterpretCast<float>();
93	    } else {
94	        dst = castBuf.Get<float>();
95	    }
96	}
97	
98	template <typename T>
99	__aicore__ inline void PrepareInvRmsTensorHelper(
100	    AscendC::LocalTensor<float> &dst,
101	    AscendC::LocalTensor<T> &out,
102	    AscendC::TBuf<AscendC::TPosition::VECCALC> &invRmsBuf)
103	{
104	    if constexpr (std::is_same_v<T, float>) {
105	        dst = out.template ReinterpretCast<float>();
106	    } else {
107	        dst = invRmsBuf.Get<float>();
108	    }
109	}
110	
111	template <typename T>
112	__aicore__ inline void FinalizeOutputTensorHelper(
113	    AscendC::LocalTensor<T> &out,
114	    AscendC::LocalTensor<float> &src,
115	    int32_t count)
116	{
117	    if constexpr (!std::is_same_v<T, float>) {
118	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
119	        AscendC::PipeBarrier<PIPE_V>();
120	    }
121	}
122	
123	template <typename F>
124	__aicore__ inline void ProcessLoop(
125	    F &&processRowFn,
126	    int32_t tasksPerCore, int32_t M, int32_t blockM, int32_t subBlockRows_)
127	{
128	    if ASCEND_IS_AIV {
129	        const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
130	        const int subBlockIdx = AscendC::GetSubBlockIdx();
131	
132	        for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
133	            const int bx = coreIdx * tasksPerCore + localIdx;
134	            if (bx >= BlockCountHelper(M, blockM)) {
135	                continue;
136	            }
137	
138	            for (int row = 0; row < subBlockRows_; ++row) {
139	                const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
140	                if (rowIdx < M) {
141	                    processRowFn(rowIdx);
142	                }
143	            }
144	        }
145	    }
146	}
