622	template <typename dataType>
623	class RmsNormSplitDKernel : public RmsNormKernelBase<dataType> {
624	public:
625	    __aicore__ inline void Init(
626	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
627	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
628	        int32_t tasksPerCore, float eps, float invN)
629	    {
630	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
631	
632	        if ASCEND_IS_AIV {
633	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
