55	    TORCH_CHECK(value.scalar_type() == dtype, "value dtype mismatch");
56	    TORCH_CHECK(max_state.scalar_type() == dtype, "max_state dtype mismatch");
57	    TORCH_CHECK(num_state.scalar_type() == dtype, "num_state dtype mismatch");
58	    TORCH_CHECK(den_state.scalar_type() == dtype, "den_state dtype mismatch");
59	
60	    TORCH_CHECK(key.is_contiguous(), "key must be contiguous");
61	    TORCH_CHECK(value.is_contiguous(), "value must be contiguous");
62	
63	    // ---- Extract dimensions ----
64	    int32_t batchSize = static_cast<int32_t>(key.sizes()[0]);
65	    int32_t seqLen = static_cast<int32_t>(key.sizes()[1]);
66	    int32_t hiddenSize = static_cast<int32_t>(key.sizes()[2]);
67	
68	    TORCH_CHECK(static_cast<int32_t>(time_decay.sizes()[0]) == hiddenSize,
69	                "time_decay shape mismatch");
70	    TORCH_CHECK(static_cast<int32_t>(time_first.sizes()[0]) == hiddenSize,
71	                "time_first shape mismatch");
72	    TORCH_CHECK(static_cast<int32_t>(value.sizes()[0]) == batchSize &&
