// RWKV Time Decay Exponential Stabilization op_host
// Tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_time_decay_exp_stabilization.h"

namespace ascend_kernel {

std::vector<at::Tensor> time_decay_exp_stabilization(
    const at::Tensor &time_decay,
    const at::Tensor &key,
    const at::Tensor &time_first,
    const at::Tensor &value,
    const at::Tensor &max_state,
    const at::Tensor &num_state,
    const at::Tensor &den_state)
{
    // ---- Input validation ----
    TORCH_CHECK(time_decay.dim() == 1, "time_decay must be [H]");
    TORCH_CHECK(key.dim() == 3, "key must be [B, S, H]");
    TORCH_CHECK(time_first.dim() == 1, "time_first must be [H]");
    TORCH_CHECK(value.dim() == 3, "value must be [B, S, H]");
    TORCH_CHECK(max_state.dim() == 2, "max_state must be [B, H]");
    TORCH_CHECK(num_state.dim() == 2, "num_state must be [B, H]");
    TORCH_CHECK(den_state.dim() == 2, "den_state must be [B, H]");

    TORCH_CHECK(
        time_decay.scalar_type() == at::kFloat ||
        time_decay.scalar_type() == at::kHalf ||
        time_decay.scalar_type() == at::kBFloat16,
        "dtype must be float32, float16, or bfloat16");

    at::ScalarType dtype = time_decay.scalar_type();
    TORCH_CHECK(key.scalar_type() == dtype, "key dtype mismatch");
    TORCH_CHECK(time_first.scalar_type() == dtype, "time_first dtype mismatch");
    TORCH_CHECK(value.scalar_type() == dtype, "value dtype mismatch");
    TORCH_CHECK(max_state.scalar_type() == dtype, "max_state dtype mismatch");
    TORCH_CHECK(num_state.scalar_type() == dtype, "num_state dtype mismatch");
    TORCH_CHECK(den_state.scalar_type() == dtype, "den_state dtype mismatch");

    // ---- Extract dimensions ----
    int32_t batchSize = static_cast<int32_t>(key.sizes()[0]);
    int32_t seqLen = static_cast<int32_t>(key.sizes()[1]);
    int32_t hiddenSize = static_cast<int32_t>(key.sizes()[2]);

    TORCH_CHECK(static_cast<int32_t>(time_decay.sizes()[0]) == hiddenSize,
                "time_decay shape mismatch");
    TORCH_CHECK(static_cast<int32_t>(time_first.sizes()[0]) == hiddenSize,
                "time_first shape mismatch");

    // ---- Allocate output tensors ----
    at::Tensor output = at::empty({batchSize, seqLen, hiddenSize}, key.options());
    at::Tensor out_max_state = at::empty({batchSize, hiddenSize}, max_state.options());
    at::Tensor out_num_state = at::empty({batchSize, hiddenSize}, num_state.options());
    at::Tensor out_den_state = at::empty({batchSize, hiddenSize}, den_state.options());

    // ---- Platform info ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());

    // ---- Tiling: split batch dimension across cores ----
    int32_t usedCoreNum = std::min(coreNum, batchSize);
    if (usedCoreNum < 1) usedCoreNum = 1;
    int32_t tasksPerCore = (batchSize + usedCoreNum - 1) / usedCoreNum;

    // ---- dtype flag: 0=fp32, 1=fp16, 2=bf16 ----
    int64_t dtypeFlag = 0;
    if (dtype == at::kHalf) {
        dtypeFlag = 1;
    } else if (dtype == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // ---- Launch kernel ----
    // All parameters must be left values for EXEC_KERNEL_CMD
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int32_t bSize = batchSize;
    int32_t sLen = seqLen;
    int32_t hSize = hiddenSize;
    int32_t tPerCore = tasksPerCore;
    int64_t dFlag = dtypeFlag;

    EXEC_KERNEL_CMD(time_decay_exp_stabilization, blockDim,
                    time_decay, key, time_first, value,
                    max_state, num_state, den_state,
                    output, out_max_state, out_num_state, out_den_state,
                    bSize, sLen, hSize, tPerCore,
                    dFlag);

    return {output, out_max_state, out_num_state, out_den_state};
}

}  // namespace ascend_kernel
