11	// RWKV Time Decay Exponential Stabilization kernel
12	// 7 inputs, 4 outputs, purely Vector-side computation
13	// One kernel entry with dtype dispatch (float32, float16, bfloat16)
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t TILE_H = 256;
18	constexpr int32_t BUFFER_NUM = 1;
19	
20	// ---------------------------------------------------------------------------
21	// Inline helpers
22	// ---------------------------------------------------------------------------
23	
24	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
25	{
26	    if (b == 0U) { return 0U; }
27	    return (a + b - 1U) / b;
28	}
29	
30	template <typename T>
31	__aicore__ inline void LoadGmToUb(
32	    AscendC::LocalTensor<T> &dst,
33	    const AscendC::GlobalTensor<T> &src,
34	    uint32_t count)
35	{
36	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
37	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
38	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
39	}
40	
41	template <typename T>
42	__aicore__ inline void StoreUbToGm(
43	    AscendC::GlobalTensor<T> &dst,
44	    const AscendC::LocalTensor<T> &src,
45	    uint32_t count)
46	{
47	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
48	    AscendC::DataCopyPad(dst, src, copyParams);
49	}
50	
51	template <typename T>
52	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
53	{
54	    if constexpr (std::is_same_v<T, bfloat16_t>) {
55	        return AscendC::RoundMode::CAST_ROUND;
56	    }
57	    return AscendC::RoundMode::CAST_NONE;
58	}
59	
60	// =========================================================================
61	// Main Kernel Class
62	// =========================================================================
63	
64	template <typename dataType>
65	class TimeDecayExpStabilizationKernel {
66	public:
67	    __aicore__ inline void Init(
68	        GM_ADDR time_decay, GM_ADDR key, GM_ADDR time_first, GM_ADDR value,
69	        GM_ADDR max_state, GM_ADDR num_state, GM_ADDR den_state,
70	        GM_ADDR output, GM_ADDR out_max_state, GM_ADDR out_num_state, GM_ADDR out_den_state,
71	        int32_t batchSize, int32_t seqLen, int32_t hiddenSize,
72	        int32_t batchesPerCore, int32_t coreStartBatch, int32_t coreNumBatches)
73	    {
74	        this->batchSize = batchSize;
75	        this->seqLen = seqLen;
76	        this->hiddenSize = hiddenSize;
77	        this->hTiles = hiddenSize / TILE_H;
78	        this->batchesPerCore = batchesPerCore;
79	        this->coreStartBatch = coreStartBatch;
80	        this->coreNumBatches = coreNumBatches;
81	
82	        // Set global tensors
83	        tdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(time_decay), hiddenSize);
84	        keyGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(key),
85	                               static_cast<uint64_t>(batchSize) * seqLen * hiddenSize);
86	        tfGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(time_first), hiddenSize);
87	        valGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(value),
88	                                static_cast<uint64_t>(batchSize) * seqLen * hiddenSize);
89	        msGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(max_state),
90	                              static_cast<uint64_t>(batchSize) * hiddenSize);
91	        nsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(num_state),
92	                              static_cast<uint64_t>(batchSize) * hiddenSize);
93	        dsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(den_state),
94	                              static_cast<uint64_t>(batchSize) * hiddenSize);
95	        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output),
96	                               static_cast<uint64_t>(batchSize) * seqLen * hiddenSize);
97	        outMSGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(out_max_state),
98	                                 static_cast<uint64_t>(batchSize) * hiddenSize);
99	        outNSGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(out_num_state),
100	                                 static_cast<uint64_t>(batchSize) * hiddenSize);
101	        outDSGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(out_den_state),
102	                                 static_cast<uint64_t>(batchSize) * hiddenSize);
103	
104	        InitBuffers();
105	    }
106	
107	    __aicore__ inline void InitBuffers()
108	    {
109	        if ASCEND_IS_AIV {
110	            // NBuf: 2048 elements for constants
111	            pipe.InitBuffer(inQueue_, BUFFER_NUM, static_cast<uint32_t>(TILE_H) * sizeof(dataType));
112	            pipe.InitBuffer(outQueue_, BUFFER_NUM, static_cast<uint32_t>(TILE_H) * sizeof(dataType));
113	            // Full-length constants (2048 elements each)
114	            pipe.InitBuffer(tdExpBuf_, static_cast<uint32_t>(hiddenSize) * sizeof(float));
115	            pipe.InitBuffer(tfBuf_, static_cast<uint32_t>(hiddenSize) * sizeof(float));
116	            // Cast buffers
117	            pipe.InitBuffer(castBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
118	            // Tile compute buffers (float32)
119	            pipe.InitBuffer(bufA_, static_cast<uint32_t>(TILE_H) * sizeof(float));
120	            pipe.InitBuffer(bufB_, static_cast<uint32_t>(TILE_H) * sizeof(float));
121	            pipe.InitBuffer(bufC_, static_cast<uint32_t>(TILE_H) * sizeof(float));
122	            pipe.InitBuffer(bufD_, static_cast<uint32_t>(TILE_H) * sizeof(float));
123	            pipe.InitBuffer(bufE_, static_cast<uint32_t>(TILE_H) * sizeof(float));
124	            pipe.InitBuffer(bufF_, static_cast<uint32_t>(TILE_H) * sizeof(float));
125	            // Per-tile state working copies (float32)
126	            pipe.InitBuffer(ckBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
127	            pipe.InitBuffer(cvBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
128	            pipe.InitBuffer(msBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
129	            pipe.InitBuffer(nsBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
130	            pipe.InitBuffer(dsBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
131	            pipe.InitBuffer(tdTileBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
132	            pipe.InitBuffer(tfTileBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
133	
134	            // Precompute time_decay_exp = -exp(time_decay)
135	            PrecomputeConstants();
136	        }
137	    }
138	
139	    __aicore__ inline void PrecomputeConstants()
140	    {
141	        // Load full time_decay [hiddenSize], compute -exp, store in tdExpBuf_
142	        AscendC::LocalTensor<float> tdExpLocal = tdExpBuf_.Get<float>();
143	        AscendC::LocalTensor<dataType> inLocal;
144	
145	        // Process time_decay in tiles
146	        for (int32_t h = 0; h < hTiles; ++h) {
147	            int32_t hStart = h * TILE_H;
148	            inLocal = inQueue_.AllocTensor<dataType>();
149	            LoadGmToUb(inLocal, tdGM_[hStart], TILE_H);
150	            inQueue_.EnQue(inLocal);
151	            inLocal = inQueue_.DeQue<dataType>();
152	            AscendC::LocalTensor<float> f32Local = castBuf_.Get<float>();
153	            if constexpr (std::is_same_v<dataType, float>) {
154	                f32Local = inLocal.template ReinterpretCast<float>();
155	            } else {
156	                AscendC::Cast(f32Local, inLocal, AscendC::RoundMode::CAST_NONE, TILE_H);
157	                AscendC::PipeBarrier<PIPE_V>();
158	            }
159	            AscendC::Exp(tdExpLocal[hStart], f32Local, TILE_H);
160	            AscendC::PipeBarrier<PIPE_V>();
161	            AscendC::Muls(f32Local, tdExpLocal[hStart], -1.0f, TILE_H);
162	            AscendC::PipeBarrier<PIPE_V>();
163	            // Store result (negation of exp)
164	            AscendC::DataCopy(tdExpLocal[hStart], f32Local, TILE_H);
165	            AscendC::PipeBarrier<PIPE_V>();
166	            inQueue_.FreeTensor(inLocal);
167	        }
168	
169	        // Load full time_first [hiddenSize], store as float32 in tfBuf_
170	        AscendC::LocalTensor<float> tfLocal = tfBuf_.Get<float>();
171	        for (int32_t h = 0; h < hTiles; ++h) {
172	            int32_t hStart = h * TILE_H;
173	            inLocal = inQueue_.AllocTensor<dataType>();
174	            LoadGmToUb(inLocal, tfGM_[hStart], TILE_H);
175	            inQueue_.EnQue(inLocal);
176	            inLocal = inQueue_.DeQue<dataType>();
177	            AscendC::LocalTensor<float> f32Local = castBuf_.Get<float>();
178	            if constexpr (std::is_same_v<dataType, float>) {
179	                f32Local = inLocal.template ReinterpretCast<float>();
180	            } else {
181	                AscendC::Cast(f32Local, inLocal, AscendC::RoundMode::CAST_NONE, TILE_H);
182	                AscendC::PipeBarrier<PIPE_V>();
183	            }
184	            AscendC::DataCopy(tfLocal[hStart], f32Local, TILE_H);
185	            AscendC::PipeBarrier<PIPE_V>();
186	            inQueue_.FreeTensor(inLocal);
187	        }
188	    }
189	
190	    __aicore__ inline void Process()
191	    {
192	        if ASCEND_IS_AIV {
193	            for (int32_t bi = 0; bi < coreNumBatches; ++bi) {
194	                int32_t b = coreStartBatch + bi;
195	                if (b >= batchSize) continue;
196	                ProcessBatch(b);
197	            }
198	        }
199	    }
200	
201	private:
202	    // =====================================================================
203	    // Process one batch: sequential over timesteps, tiled over hidden
204	    // =====================================================================
205	    __aicore__ inline void ProcessBatch(int32_t b)
206	    {
207	        for (int32_t t = 0; t < seqLen; ++t) {
208	            for (int32_t hIdx = 0; hIdx < hTiles; ++hIdx) {
209	                int32_t hStart = hIdx * TILE_H;
210	                ProcessTile(b, t, hStart);
211	            }
212	        }
213	
214	        // Copy final state to output arrays
215	        for (int32_t hIdx = 0; hIdx < hTiles; ++hIdx) {
216	            int32_t hStart = hIdx * TILE_H;
217	            CopyOutFinalState(b, hStart);
218	        }
219	    }
220	
221	    // =====================================================================
222	    // Process one (batch, timestep, hidden_tile)
223	    // =====================================================================
224	    __aicore__ inline void ProcessTile(int32_t b, int32_t t, int32_t hStart)
225	    {
226	        // ---- Load input tiles ----
227	        AscendC::LocalTensor<float> tdBuf = tdExpBuf_.Get<float>();
228	        AscendC::LocalTensor<float> tfF32 = tfBuf_.Get<float>();
229	        AscendC::LocalTensor<float> tdTile = tdTileBuf_.Get<float>();
230	        AscendC::LocalTensor<float> tfTile = tfTileBuf_.Get<float>();
231	
232	        // Copy constant tiles from their full buffers
233	        AscendC::DataCopy(tdTile, tdBuf[hStart], TILE_H);
234	        AscendC::PipeBarrier<PIPE_V>();
235	        AscendC::DataCopy(tfTile, tfF32[hStart], TILE_H);
236	        AscendC::PipeBarrier<PIPE_V>();
237	
238	        // Load key[b, t, hStart] → ckBuf_
239	        AscendC::LocalTensor<float> ckF32 = ckBuf_.Get<float>();
240	        LoadTensorToFloat32(keyGM_[static_cast<uint64_t>(b) * seqLen * hiddenSize +
241	                                    static_cast<uint64_t>(t) * hiddenSize + hStart],
242	                            ckF32, TILE_H);
243	
244	        // Load value[b, t, hStart] → cvBuf_
245	        AscendC::LocalTensor<float> cvF32 = cvBuf_.Get<float>();
246	        LoadTensorToFloat32(valGM_[static_cast<uint64_t>(b) * seqLen * hiddenSize +
247	                                    static_cast<uint64_t>(t) * hiddenSize + hStart],
248	                            cvF32, TILE_H);
249	
250	        // Load max_state[b, hStart] → msBuf_
251	        AscendC::LocalTensor<float> msF32 = msBuf_.Get<float>();
252	        LoadTensorToFloat32(msGM_[static_cast<uint64_t>(b) * hiddenSize + hStart],
253	                            msF32, TILE_H);
254	
255	        // Load num_state[b, hStart] → nsBuf_
256	        AscendC::LocalTensor<float> nsF32 = nsBuf_.Get<float>();
257	        LoadTensorToFloat32(nsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart],
258	                            nsF32, TILE_H);
259	
260	        // Load den_state[b, hStart] → dsBuf_
261	        AscendC::LocalTensor<float> dsF32 = dsBuf_.Get<float>();
262	        LoadTensorToFloat32(dsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart],
263	                            dsF32, TILE_H);
264	
265	        // ---- Get compute buffers ----
266	        AscendC::LocalTensor<float> tA = bufA_.Get<float>();
267	        AscendC::LocalTensor<float> tB = bufB_.Get<float>();
268	        AscendC::LocalTensor<float> tC = bufC_.Get<float>();
269	        AscendC::LocalTensor<float> tD = bufD_.Get<float>();
270	        AscendC::LocalTensor<float> tE = bufE_.Get<float>();
271	        AscendC::LocalTensor<float> tF = bufF_.Get<float>();
272	
273	        // =========================================================
274	        // Phase A: Compute output for this timestep and tile
275	        // =========================================================
276	
277	        // tA = current_key + time_first
278	        AscendC::Add(tA, ckF32, tfTile, TILE_H);
279	        AscendC::PipeBarrier<PIPE_V>();
280	
281	        // tB = max_for_output = max(max_state, tA)
282	        AscendC::Max(tB, msF32, tA, TILE_H);
283	        AscendC::PipeBarrier<PIPE_V>();
284	
285	        // tC = max_state - max_for_output
286	        AscendC::Sub(tC, msF32, tB, TILE_H);
287	        AscendC::PipeBarrier<PIPE_V>();
288	
289	        // tD = e1_output = exp(tC)
290	        AscendC::Exp(tD, tC, TILE_H);
291	        AscendC::PipeBarrier<PIPE_V>();
292	
293	        // tE = current_key + time_first - max_for_output = tA - tB
294	        AscendC::Sub(tE, tA, tB, TILE_H);
295	        AscendC::PipeBarrier<PIPE_V>();
296	
297	        // tF = e2_output = exp(tE)
298	        AscendC::Exp(tF, tE, TILE_H);
299	        AscendC::PipeBarrier<PIPE_V>();
300	
301	        // tA = e1_output * num_state
302	        AscendC::Mul(tA, tD, nsF32, TILE_H);
303	        AscendC::PipeBarrier<PIPE_V>();
304	
305	        // tB = e2_output * current_value
306	        AscendC::Mul(tB, tF, cvF32, TILE_H);
307	        AscendC::PipeBarrier<PIPE_V>();
308	
309	        // tC = numerator = tA + tB
310	        AscendC::Add(tC, tA, tB, TILE_H);
311	        AscendC::PipeBarrier<PIPE_V>();
312	
313	        // tA = e1_output * den_state  (reuse tA after the previous add)
314	        AscendC::Mul(tA, tD, dsF32, TILE_H);
315	        AscendC::PipeBarrier<PIPE_V>();
316	
317	        // tB = denominator = tA + e2_output  (reuse tB after the previous mul)
318	        AscendC::Add(tB, tA, tF, TILE_H);
319	        AscendC::PipeBarrier<PIPE_V>();
320	
321	        // tD = result = numerator / denominator
322	        AscendC::Div(tD, tC, tB, TILE_H);
323	        AscendC::PipeBarrier<PIPE_V>();
324	
325	        // Write output[b, t, hStart]
326	        StoreFloat32ToTensor(
327	            outGM_[static_cast<uint64_t>(b) * seqLen * hiddenSize +
328	                   static_cast<uint64_t>(t) * hiddenSize + hStart],
329	            tD, TILE_H);
330	
331	        // =========================================================
332	        // Phase B: Update state for next timestep
333	        // =========================================================
334	
335	        // tA = max_state + time_decay_exp
336	        AscendC::Add(tA, msF32, tdTile, TILE_H);
337	        AscendC::PipeBarrier<PIPE_V>();
338	
339	        // tB = max_for_state = max(tA, current_key)
340	        AscendC::Max(tB, tA, ckF32, TILE_H);
341	        AscendC::PipeBarrier<PIPE_V>();
342	
343	        // tC = max_state + time_decay_exp - max_for_state = tA - tB
344	        AscendC::Sub(tC, tA, tB, TILE_H);
345	        AscendC::PipeBarrier<PIPE_V>();
346	
347	        // tD = e1_state = exp(tC)
348	        AscendC::Exp(tD, tC, TILE_H);
349	        AscendC::PipeBarrier<PIPE_V>();
350	
351	        // tE = current_key - max_for_state
352	        AscendC::Sub(tE, ckF32, tB, TILE_H);
353	        AscendC::PipeBarrier<PIPE_V>();
354	
355	        // tF = e2_state = exp(tE)
356	        AscendC::Exp(tF, tE, TILE_H);
357	        AscendC::PipeBarrier<PIPE_V>();
358	
359	        // tA = e1_state * num_state
360	        AscendC::Mul(tA, tD, nsF32, TILE_H);
361	        AscendC::PipeBarrier<PIPE_V>();
362	
363	        // tB = e2_state * current_value
364	        AscendC::Mul(tB, tF, cvF32, TILE_H);
365	        AscendC::PipeBarrier<PIPE_V>();
366	
367	        // tC = num_state_new = tA + tB
368	        AscendC::Add(tC, tA, tB, TILE_H);
369	        AscendC::PipeBarrier<PIPE_V>();
370	
371	        // tA = e1_state * den_state  (reuse)
372	        AscendC::Mul(tA, tD, dsF32, TILE_H);
373	        AscendC::PipeBarrier<PIPE_V>();
374	
375	        // tB = den_state_new = tA + e2_state  (reuse)
376	        AscendC::Add(tB, tA, tF, TILE_H);
377	        AscendC::PipeBarrier<PIPE_V>();
378	
379	        // tD = max_state_new = tB (max_for_state, from tB above)
380	        // We need to preserve tB and compute tD = max_for_state
381	        // tB currently holds den_state_new, tC holds num_state_new
382	        // Use tD for max_state_new = max_for_state (stored in tB earlier, now overwritten)
383	        // Recompute: the max_for_state was in tB before it got overwritten
384	        // Actually looking at the code flow more carefully:
385	        //   tB = max_for_state (after Max)
386	        //   tC = tA - tB (tA-tB state subtraction)
387	        //   tD = exp(tC)
388	        //   tE = ckF32 - tB (key - max_for_state)
389	        //   tF = exp(tE)
390	        //   tA = e1_state * nsF32, tB = e2_state * cvF32, tC = tA + tB
391	        //   tA = e1_state * dsF32, tB = tA + e2_state
392	        // So tB (the max_for_state) was overwritten by e2_state * cvF32,
393	        // then tB = tA + e2_state = den_state_new
394	        // tC = num_state_new
395	        // We need max_for_state separately.
396	        // Let me just recompute it: tD = max(msF32 + tdTile, ckF32)
397	        AscendC::Add(tD, msF32, tdTile, TILE_H);
398	        AscendC::PipeBarrier<PIPE_V>();
399	        AscendC::Max(tD, tD, ckF32, TILE_H);
400	        AscendC::PipeBarrier<PIPE_V>();
401	        // Now tD = max_state_new, tC = num_state_new, tB = den_state_new
402	
403	        // ---- Write updated state back to GM ----
404	        StoreFloat32ToTensor(msGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], tD, TILE_H);
405	        StoreFloat32ToTensor(nsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], tC, TILE_H);
406	        StoreFloat32ToTensor(dsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], tB, TILE_H);
407	    }
408	
409	    // =====================================================================
410	    // Copy final state to output arrays
411	    // =====================================================================
412	    __aicore__ inline void CopyOutFinalState(int32_t b, int32_t hStart)
413	    {
414	        AscendC::LocalTensor<dataType> inLocal;
415	        AscendC::LocalTensor<dataType> outLocal;
416	
417	        // out_max_state[b, hStart]
418	        inLocal = inQueue_.AllocTensor<dataType>();
419	        LoadGmToUb(inLocal, msGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], TILE_H);
420	        inQueue_.EnQue(inLocal);
421	        outLocal = outQueue_.AllocTensor<dataType>();
422	        inLocal = inQueue_.DeQue<dataType>();
423	        AscendC::DataCopy(outLocal, inLocal, TILE_H);
424	        AscendC::PipeBarrier<PIPE_V>();
425	        outQueue_.EnQue(outLocal);
426	        outLocal = outQueue_.DeQue<dataType>();
427	        StoreUbToGm(outMSGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], outLocal, TILE_H);
428	        outQueue_.FreeTensor(outLocal);
429	        inQueue_.FreeTensor(inLocal);
430	
431	        // out_num_state[b, hStart]
432	        inLocal = inQueue_.AllocTensor<dataType>();
433	        LoadGmToUb(inLocal, nsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], TILE_H);
434	        inQueue_.EnQue(inLocal);
435	        outLocal = outQueue_.AllocTensor<dataType>();
436	        inLocal = inQueue_.DeQue<dataType>();
437	        AscendC::DataCopy(outLocal, inLocal, TILE_H);
438	        AscendC::PipeBarrier<PIPE_V>();
439	        outQueue_.EnQue(outLocal);
440	        outLocal = outQueue_.DeQue<dataType>();
441	        StoreUbToGm(outNSGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], outLocal, TILE_H);
442	        outQueue_.FreeTensor(outLocal);
443	        inQueue_.FreeTensor(inLocal);
444	
445	        // out_den_state[b, hStart]
446	        inLocal = inQueue_.AllocTensor<dataType>();
447	        LoadGmToUb(inLocal, dsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], TILE_H);
448	        inQueue_.EnQue(inLocal);
449	        outLocal = outQueue_.AllocTensor<dataType>();
450	        inLocal = inQueue_.DeQue<dataType>();
451	        AscendC::DataCopy(outLocal, inLocal, TILE_H);
452	        AscendC::PipeBarrier<PIPE_V>();
453	        outQueue_.EnQue(outLocal);
454	        outLocal = outQueue_.DeQue<dataType>();
455	        StoreUbToGm(outDSGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], outLocal, TILE_H);
456	        outQueue_.FreeTensor(outLocal);
457	        inQueue_.FreeTensor(inLocal);
458	    }
459	
460	    // =====================================================================
461	    // Helper: Load GM float16/bf16/float32 → UB float32
462	    // =====================================================================
463	    __aicore__ inline void LoadTensorToFloat32(
464	        const AscendC::GlobalTensor<dataType> &gmSrc,
465	        AscendC::LocalTensor<float> &f32Dst,
466	        int32_t count)
467	    {
468	        AscendC::LocalTensor<dataType> inLocal = inQueue_.AllocTensor<dataType>();
469	        LoadGmToUb(inLocal, gmSrc, static_cast<uint32_t>(count));
470	        inQueue_.EnQue(inLocal);
471	        inLocal = inQueue_.DeQue<dataType>();
472	        if constexpr (std::is_same_v<dataType, float>) {
473	            AscendC::LocalTensor<float> tmp = inLocal.template ReinterpretCast<float>();
474	            AscendC::DataCopy(f32Dst, tmp, static_cast<uint32_t>(count));
475	        } else {
476	            AscendC::Cast(f32Dst, inLocal, AscendC::RoundMode::CAST_NONE, count);
477	        }
478	        AscendC::PipeBarrier<PIPE_V>();
479	        inQueue_.FreeTensor(inLocal);
480	    }
481	
482	    // =====================================================================
483	    // Helper: Store UB float32 → GM float16/bf16/float32
484	    // =====================================================================
485	    __aicore__ inline void StoreFloat32ToTensor(
486	        AscendC::GlobalTensor<dataType> &gmDst,
487	        AscendC::LocalTensor<float> &f32Src,
488	        int32_t count)
489	    {
490	        AscendC::LocalTensor<dataType> outLocal = outQueue_.AllocTensor<dataType>();
491	        if constexpr (std::is_same_v<dataType, float>) {
492	            AscendC::LocalTensor<float> tmp = outLocal.template ReinterpretCast<float>();
493	            AscendC::DataCopy(tmp, f32Src, static_cast<uint32_t>(count));
494	        } else {
495	            AscendC::Cast(outLocal, f32Src, OutputRoundModeHelper<dataType>(), count);
496	        }
497	        AscendC::PipeBarrier<PIPE_V>();
498	        outQueue_.EnQue(outLocal);
499	        outLocal = outQueue_.DeQue<dataType>();
500	        StoreUbToGm(gmDst, outLocal, static_cast<uint32_t>(count));
501	        outQueue_.FreeTensor(outLocal);
502	    }
503	
504	private:
505	    int32_t batchSize = 0;
506	    int32_t seqLen = 0;
507	    int32_t hiddenSize = 0;
508	    int32_t hTiles = 0;
509	    int32_t batchesPerCore = 0;
510	    int32_t coreStartBatch = 0;
511	    int32_t coreNumBatches = 0;
512	
513	    AscendC::TPipe pipe;
514	
515	    // Global tensors
516	    AscendC::GlobalTensor<dataType> tdGM_;
517	    AscendC::GlobalTensor<dataType> keyGM_;
518	    AscendC::GlobalTensor<dataType> tfGM_;
519	    AscendC::GlobalTensor<dataType> valGM_;
520	    AscendC::GlobalTensor<dataType> msGM_;
521	    AscendC::GlobalTensor<dataType> nsGM_;
522	    AscendC::GlobalTensor<dataType> dsGM_;
523	    AscendC::GlobalTensor<dataType> outGM_;
524	    AscendC::GlobalTensor<dataType> outMSGM_;
525	    AscendC::GlobalTensor<dataType> outNSGM_;
526	    AscendC::GlobalTensor<dataType> outDSGM_;
527	
528	    // Queues
529	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
530	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
531	
532	    // Constant buffers
533	    AscendC::TBuf<AscendC::TPosition::VECCALC> tdExpBuf_;
534	    AscendC::TBuf<AscendC::TPosition::VECCALC> tfBuf_;
535	
536	    // Cast buffer
537	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
538	
539	    // Compute buffers (float32 tile intermediates)
540	    AscendC::TBuf<AscendC::TPosition::VECCALC> bufA_;
541	    AscendC::TBuf<AscendC::TPosition::VECCALC> bufB_;
542	    AscendC::TBuf<AscendC::TPosition::VECCALC> bufC_;
543	    AscendC::TBuf<AscendC::TPosition::VECCALC> bufD_;
544	    AscendC::TBuf<AscendC::TPosition::VECCALC> bufE_;
545	    AscendC::TBuf<AscendC::TPosition::VECCALC> bufF_;
546	
547	    // Per-tile state working copies
548	    AscendC::TBuf<AscendC::TPosition::VECCALC> ckBuf_;
549	    AscendC::TBuf<AscendC::TPosition::VECCALC> cvBuf_;
550	    AscendC::TBuf<AscendC::TPosition::VECCALC> msBuf_;
551	    AscendC::TBuf<AscendC::TPosition::VECCALC> nsBuf_;
552	    AscendC::TBuf<AscendC::TPosition::VECCALC> dsBuf_;
553	    AscendC::TBuf<AscendC::TPosition::VECCALC> tdTileBuf_;
554	    AscendC::TBuf<AscendC::TPosition::VECCALC> tfTileBuf_;
555	};
556	
557	// =========================================================================
558	// dtype dispatch helper
559	// =========================================================================
560	
561	template <template <typename> class Kernel>
562	__aicore__ inline void DispatchKernel(
563	    GM_ADDR time_decay, GM_ADDR key, GM_ADDR time_first, GM_ADDR value,
564	    GM_ADDR max_state, GM_ADDR num_state, GM_ADDR den_state,
565	    GM_ADDR output, GM_ADDR out_max_state, GM_ADDR out_num_state, GM_ADDR out_den_state,
566	    int32_t batchSize, int32_t seqLen, int32_t hiddenSize,
567	    int32_t batchesPerCore, int32_t coreStartBatch, int32_t coreNumBatches,
568	    int64_t dtypeFlag)
569	{
570	    if (dtypeFlag == 0) {
571	        Kernel<float> kernel;
572	        kernel.Init(time_decay, key, time_first, value,
573	                    max_state, num_state, den_state,
574	                    output, out_max_state, out_num_state, out_den_state,
575	                    batchSize, seqLen, hiddenSize,
576	                    batchesPerCore, coreStartBatch, coreNumBatches);
577	        kernel.Process();
578	    } else if (dtypeFlag == 1) {
579	        Kernel<half> kernel;
580	        kernel.Init(time_decay, key, time_first, value,
581	                    max_state, num_state, den_state,
582	                    output, out_max_state, out_num_state, out_den_state,
583	                    batchSize, seqLen, hiddenSize,
584	                    batchesPerCore, coreStartBatch, coreNumBatches);
585	        kernel.Process();
586	    } else {
587	        Kernel<bfloat16_t> kernel;
588	        kernel.Init(time_decay, key, time_first, value,
589	                    max_state, num_state, den_state,
590	                    output, out_max_state, out_num_state, out_den_state,
591	                    batchSize, seqLen, hiddenSize,
592	                    batchesPerCore, coreStartBatch, coreNumBatches);
593	        kernel.Process();
594	    }
595	}
596	
597	// =========================================================================
598	// Kernel entry point
599	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
600	// =========================================================================
601	
602	extern "C" __global__ __aicore__ void time_decay_exp_stabilization(
603	    GM_ADDR time_decay, GM_ADDR key, GM_ADDR time_first, GM_ADDR value,
604	    GM_ADDR max_state, GM_ADDR num_state, GM_ADDR den_state,
605	    GM_ADDR output, GM_ADDR out_max_state, GM_ADDR out_num_state, GM_ADDR out_den_state,
606	    int32_t batchSize, int32_t seqLen, int32_t hiddenSize,
607	    int32_t batchesPerCore, int32_t coreStartBatch, int32_t coreNumBatches,
608	    int64_t dtypeFlag)
609	{
610	    DispatchKernel<TimeDecayExpStabilizationKernel>(
611	        time_decay, key, time_first, value,
612	        max_state, num_state, den_state,
613	        output, out_max_state, out_num_state, out_den_state,
614	        batchSize, seqLen, hiddenSize,
615	        batchesPerCore, coreStartBatch, coreNumBatches,
616	        dtypeFlag);
617	}
