// RWKV Time Decay Exponential Stabilization kernel
// 7 inputs, 4 outputs, purely Vector-side computation
// One kernel entry with dtype dispatch (float32, float16, bfloat16)
// Each core processes some number of batches using GetBlockIdx()

#include "kernel_operator.h"

constexpr int32_t TILE_H = 256;
constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> &dst,
    const AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

// =========================================================================
// Main Kernel Class
// =========================================================================

template <typename dataType>
class TimeDecayExpStabilizationKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR time_decay, GM_ADDR key, GM_ADDR time_first, GM_ADDR value,
        GM_ADDR max_state, GM_ADDR num_state, GM_ADDR den_state,
        GM_ADDR output, GM_ADDR out_max_state, GM_ADDR out_num_state, GM_ADDR out_den_state,
        int32_t batchSize, int32_t seqLen, int32_t hiddenSize, int32_t tasksPerCoreVal)
    {
        this->batchSize = batchSize;
        this->seqLen = seqLen;
        this->hiddenSize = hiddenSize;
        this->hTiles = hiddenSize / TILE_H;
        this->tasksPerCore = tasksPerCoreVal;

        // Set global tensors
        tdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(time_decay), hiddenSize);
        keyGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(key),
                               static_cast<uint64_t>(batchSize) * seqLen * hiddenSize);
        tfGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(time_first), hiddenSize);
        valGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(value),
                                static_cast<uint64_t>(batchSize) * seqLen * hiddenSize);
        msGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(max_state),
                              static_cast<uint64_t>(batchSize) * hiddenSize);
        nsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(num_state),
                              static_cast<uint64_t>(batchSize) * hiddenSize);
        dsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(den_state),
                              static_cast<uint64_t>(batchSize) * hiddenSize);
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output),
                               static_cast<uint64_t>(batchSize) * seqLen * hiddenSize);
        outMSGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(out_max_state),
                                 static_cast<uint64_t>(batchSize) * hiddenSize);
        outNSGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(out_num_state),
                                 static_cast<uint64_t>(batchSize) * hiddenSize);
        outDSGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(out_den_state),
                                 static_cast<uint64_t>(batchSize) * hiddenSize);

        if ASCEND_IS_AIV {
            InitBuffers();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx();
            int32_t startBatch = coreIdx * tasksPerCore;
            int32_t endBatch = (startBatch + tasksPerCore < batchSize) ?
                               (startBatch + tasksPerCore) : batchSize;

            for (int32_t b = startBatch; b < endBatch; ++b) {
                ProcessBatch(b);
            }
        }
    }

private:
    // =====================================================================
    // Init UB buffers and precompute constants
    // =====================================================================
    __aicore__ inline void InitBuffers()
    {
        pipe.InitBuffer(inQueue_, BUFFER_NUM, static_cast<uint32_t>(TILE_H) * sizeof(dataType));
        pipe.InitBuffer(outQueue_, BUFFER_NUM, static_cast<uint32_t>(TILE_H) * sizeof(dataType));
        pipe.InitBuffer(tdExpBuf_, static_cast<uint32_t>(hiddenSize) * sizeof(float));
        pipe.InitBuffer(tfBuf_, static_cast<uint32_t>(hiddenSize) * sizeof(float));
        pipe.InitBuffer(castBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(bufA_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(bufB_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(bufC_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(bufD_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(bufE_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(bufF_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(ckBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(cvBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(msBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(nsBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(dsBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(tdTileBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));
        pipe.InitBuffer(tfTileBuf_, static_cast<uint32_t>(TILE_H) * sizeof(float));

        PrecomputeConstants();
    }

    // =====================================================================
    // Precompute time_decay_exp = -exp(time_decay) and load time_first
    // =====================================================================
    __aicore__ inline void PrecomputeConstants()
    {
        AscendC::LocalTensor<dataType> inLocal;
        AscendC::LocalTensor<float> tdExpLocal = tdExpBuf_.Get<float>();
        AscendC::LocalTensor<float> tfLocal = tfBuf_.Get<float>();

        for (int32_t h = 0; h < hTiles; ++h) {
            int32_t hStart = h * TILE_H;

            // Load time_decay[hStart:hStart+TILE_H], compute -exp
            inLocal = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(inLocal, tdGM_[hStart], TILE_H);
            inQueue_.EnQue(inLocal);
            inLocal = inQueue_.DeQue<dataType>();
            AscendC::LocalTensor<float> f32Local = castBuf_.Get<float>();
            if constexpr (std::is_same_v<dataType, float>) {
                f32Local = inLocal.template ReinterpretCast<float>();
            } else {
                AscendC::Cast(f32Local, inLocal, AscendC::RoundMode::CAST_NONE, TILE_H);
                AscendC::PipeBarrier<PIPE_V>();
            }
            // f32Local now holds time_decay as float32
            AscendC::Exp(tdExpLocal[hStart], f32Local, TILE_H);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Muls(f32Local, tdExpLocal[hStart], -1.0f, TILE_H);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopy(tdExpLocal[hStart], f32Local, TILE_H);
            AscendC::PipeBarrier<PIPE_V>();
            inQueue_.FreeTensor(inLocal);

            // Load time_first[hStart:hStart+TILE_H] → tfBuf (float32)
            inLocal = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(inLocal, tfGM_[hStart], TILE_H);
            inQueue_.EnQue(inLocal);
            inLocal = inQueue_.DeQue<dataType>();
            if constexpr (std::is_same_v<dataType, float>) {
                f32Local = inLocal.template ReinterpretCast<float>();
            } else {
                AscendC::Cast(f32Local, inLocal, AscendC::RoundMode::CAST_NONE, TILE_H);
                AscendC::PipeBarrier<PIPE_V>();
            }
            AscendC::DataCopy(tfLocal[hStart], f32Local, TILE_H);
            AscendC::PipeBarrier<PIPE_V>();
            inQueue_.FreeTensor(inLocal);
        }
    }

    // =====================================================================
    // Process one batch: sequential over timesteps, tiled over hidden
    // =====================================================================
    __aicore__ inline void ProcessBatch(int32_t b)
    {
        for (int32_t t = 0; t < seqLen; ++t) {
            for (int32_t hIdx = 0; hIdx < hTiles; ++hIdx) {
                ProcessTile(b, t, hIdx * TILE_H);
            }
        }

        // Copy final state to output arrays
        for (int32_t hIdx = 0; hIdx < hTiles; ++hIdx) {
            CopyOutFinalState(b, hIdx * TILE_H);
        }
    }

    // =====================================================================
    // Process one (batch, timestep, hidden_start) tile
    // =====================================================================
    __aicore__ inline void ProcessTile(int32_t b, int32_t t, int32_t hStart)
    {
        // ---- Get constant tile slices ----
        AscendC::LocalTensor<float> tdExpFull = tdExpBuf_.Get<float>();
        AscendC::LocalTensor<float> tfFull = tfBuf_.Get<float>();
        AscendC::LocalTensor<float> tdTile = tdTileBuf_.Get<float>();
        AscendC::LocalTensor<float> tfTile = tfTileBuf_.Get<float>();

        AscendC::DataCopy(tdTile, tdExpFull[hStart], TILE_H);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::DataCopy(tfTile, tfFull[hStart], TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // ---- Load data tiles from GM to UB (float32) ----
        AscendC::LocalTensor<float> ckF32 = ckBuf_.Get<float>();
        LoadTensor(keyGM_[static_cast<uint64_t>(b) * seqLen * hiddenSize +
                           static_cast<uint64_t>(t) * hiddenSize + hStart], ckF32);

        AscendC::LocalTensor<float> cvF32 = cvBuf_.Get<float>();
        LoadTensor(valGM_[static_cast<uint64_t>(b) * seqLen * hiddenSize +
                           static_cast<uint64_t>(t) * hiddenSize + hStart], cvF32);

        AscendC::LocalTensor<float> msF32 = msBuf_.Get<float>();
        LoadTensor(msGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], msF32);

        AscendC::LocalTensor<float> nsF32 = nsBuf_.Get<float>();
        LoadTensor(nsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], nsF32);

        AscendC::LocalTensor<float> dsF32 = dsBuf_.Get<float>();
        LoadTensor(dsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], dsF32);

        // ---- Get compute buffers (float32) ----
        AscendC::LocalTensor<float> tA = bufA_.Get<float>();
        AscendC::LocalTensor<float> tB = bufB_.Get<float>();
        AscendC::LocalTensor<float> tC = bufC_.Get<float>();
        AscendC::LocalTensor<float> tD = bufD_.Get<float>();
        AscendC::LocalTensor<float> tE = bufE_.Get<float>();
        AscendC::LocalTensor<float> tF = bufF_.Get<float>();

        // =============================================================
        // Phase A: Compute output[b, t, hStart:hStart+TILE_H]
        // =============================================================

        // tA = current_key + time_first
        AscendC::Add(tA, ckF32, tfTile, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tB = max_for_output = max(max_state, tA)
        AscendC::Max(tB, msF32, tA, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tC = max_state - max_for_output
        AscendC::Sub(tC, msF32, tB, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tD = e1_output = exp(tC)
        AscendC::Exp(tD, tC, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tE = tA - tB = current_key + tf - max_for_output
        AscendC::Sub(tE, tA, tB, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tF = e2_output = exp(tE)
        AscendC::Exp(tF, tE, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tA = e1_output * num_state
        AscendC::Mul(tA, tD, nsF32, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tB = e2_output * current_value
        AscendC::Mul(tB, tF, cvF32, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tC = numerator = tA + tB
        AscendC::Add(tC, tA, tB, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tA = e1_output * den_state
        AscendC::Mul(tA, tD, dsF32, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tB = denominator = tA + e2_output
        AscendC::Add(tB, tA, tF, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tD = result = numerator / denominator
        AscendC::Div(tD, tC, tB, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // Write output[b, t, hStart]
        StoreTensor(outGM_[static_cast<uint64_t>(b) * seqLen * hiddenSize +
                           static_cast<uint64_t>(t) * hiddenSize + hStart], tD);

        // =============================================================
        // Phase B: Update state for next timestep
        // =============================================================

        // tA = max_state + time_decay_exp
        AscendC::Add(tA, msF32, tdTile, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tB = max_for_state = max(tA, current_key) -- saved for later
        AscendC::Max(tB, tA, ckF32, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // Save max_for_state to tE since tB will be overwritten
        AscendC::DataCopy(tE, tB, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tC = tA - tB = max_state+td_exp - max_for_state
        AscendC::Sub(tC, tA, tB, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tD = e1_state = exp(tC)
        AscendC::Exp(tD, tC, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tB = current_key - max_for_state (reuse tB = tE = max_for_state)
        AscendC::Sub(tB, ckF32, tE, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tF = e2_state = exp(tB)
        AscendC::Exp(tF, tB, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tA = e1_state * num_state
        AscendC::Mul(tA, tD, nsF32, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tB = e2_state * current_value
        AscendC::Mul(tB, tF, cvF32, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tC = num_state_new = tA + tB
        AscendC::Add(tC, tA, tB, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tA = e1_state * den_state
        AscendC::Mul(tA, tD, dsF32, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tB = den_state_new = tA + e2_state
        AscendC::Add(tB, tA, tF, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tD = max_state_new (from saved tE)
        AscendC::DataCopy(tD, tE, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();

        // tD = max_state_new, tC = num_state_new, tB = den_state_new
        // Write state back to GM
        StoreTensor(msGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], tD);
        StoreTensor(nsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], tC);
        StoreTensor(dsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], tB);
    }

    // =====================================================================
    // Copy final state to output arrays after all timesteps
    // =====================================================================
    __aicore__ inline void CopyOutFinalState(int32_t b, int32_t hStart)
    {
        AscendC::LocalTensor<dataType> inLocal;
        AscendC::LocalTensor<dataType> outLocal;

        // out_max_state
        inLocal = inQueue_.AllocTensor<dataType>();
        LoadGmToUb(inLocal, msGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], TILE_H);
        inQueue_.EnQue(inLocal);
        outLocal = outQueue_.AllocTensor<dataType>();
        inLocal = inQueue_.DeQue<dataType>();
        AscendC::DataCopy(outLocal, inLocal, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();
        outQueue_.EnQue(outLocal);
        outLocal = outQueue_.DeQue<dataType>();
        StoreUbToGm(outMSGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], outLocal, TILE_H);
        outQueue_.FreeTensor(outLocal);
        inQueue_.FreeTensor(inLocal);

        // out_num_state
        inLocal = inQueue_.AllocTensor<dataType>();
        LoadGmToUb(inLocal, nsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], TILE_H);
        inQueue_.EnQue(inLocal);
        outLocal = outQueue_.AllocTensor<dataType>();
        inLocal = inQueue_.DeQue<dataType>();
        AscendC::DataCopy(outLocal, inLocal, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();
        outQueue_.EnQue(outLocal);
        outLocal = outQueue_.DeQue<dataType>();
        StoreUbToGm(outNSGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], outLocal, TILE_H);
        outQueue_.FreeTensor(outLocal);
        inQueue_.FreeTensor(inLocal);

        // out_den_state
        inLocal = inQueue_.AllocTensor<dataType>();
        LoadGmToUb(inLocal, dsGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], TILE_H);
        inQueue_.EnQue(inLocal);
        outLocal = outQueue_.AllocTensor<dataType>();
        inLocal = inQueue_.DeQue<dataType>();
        AscendC::DataCopy(outLocal, inLocal, TILE_H);
        AscendC::PipeBarrier<PIPE_V>();
        outQueue_.EnQue(outLocal);
        outLocal = outQueue_.DeQue<dataType>();
        StoreUbToGm(outDSGM_[static_cast<uint64_t>(b) * hiddenSize + hStart], outLocal, TILE_H);
        outQueue_.FreeTensor(outLocal);
        inQueue_.FreeTensor(inLocal);
    }

    // =====================================================================
    // Helper: Load GM → UB float32 (with TQue for non-float dtypes)
    // =====================================================================
    __aicore__ inline void LoadTensor(
        const AscendC::GlobalTensor<dataType> &gmSrc,
        AscendC::LocalTensor<float> &f32Dst)
    {
        AscendC::LocalTensor<dataType> inLocal = inQueue_.AllocTensor<dataType>();
        LoadGmToUb(inLocal, gmSrc, TILE_H);
        inQueue_.EnQue(inLocal);
        inLocal = inQueue_.DeQue<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::LocalTensor<float> tmp = inLocal.template ReinterpretCast<float>();
            AscendC::DataCopy(f32Dst, tmp, TILE_H);
        } else {
            AscendC::Cast(f32Dst, inLocal, AscendC::RoundMode::CAST_NONE, TILE_H);
        }
        AscendC::PipeBarrier<PIPE_V>();
        inQueue_.FreeTensor(inLocal);
    }

    // =====================================================================
    // Helper: Store UB float32 → GM (with TQue for non-float dtypes)
    // =====================================================================
    __aicore__ inline void StoreTensor(
        AscendC::GlobalTensor<dataType> &gmDst,
        AscendC::LocalTensor<float> &f32Src)
    {
        AscendC::LocalTensor<dataType> outLocal = outQueue_.AllocTensor<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::LocalTensor<float> tmp = outLocal.template ReinterpretCast<float>();
            AscendC::DataCopy(tmp, f32Src, TILE_H);
        } else {
            AscendC::Cast(outLocal, f32Src, OutputRoundModeHelper<dataType>(), TILE_H);
        }
        AscendC::PipeBarrier<PIPE_V>();
        outQueue_.EnQue(outLocal);
        outLocal = outQueue_.DeQue<dataType>();
        StoreUbToGm(gmDst, outLocal, TILE_H);
        outQueue_.FreeTensor(outLocal);
    }

private:
    int32_t batchSize = 0;
    int32_t seqLen = 0;
    int32_t hiddenSize = 0;
    int32_t hTiles = 0;
    int32_t tasksPerCore = 0;

    AscendC::TPipe pipe;

    // Global tensors
    AscendC::GlobalTensor<dataType> tdGM_;
    AscendC::GlobalTensor<dataType> keyGM_;
    AscendC::GlobalTensor<dataType> tfGM_;
    AscendC::GlobalTensor<dataType> valGM_;
    AscendC::GlobalTensor<dataType> msGM_;
    AscendC::GlobalTensor<dataType> nsGM_;
    AscendC::GlobalTensor<dataType> dsGM_;
    AscendC::GlobalTensor<dataType> outGM_;
    AscendC::GlobalTensor<dataType> outMSGM_;
    AscendC::GlobalTensor<dataType> outNSGM_;
    AscendC::GlobalTensor<dataType> outDSGM_;

    // Queues
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;

    // Buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> tdExpBuf_;    // [H] float32
    AscendC::TBuf<AscendC::TPosition::VECCALC> tfBuf_;       // [H] float32
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;     // [TILE_H] float32
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufA_;        // [TILE_H] float32
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufB_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufC_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufD_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufE_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufF_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> ckBuf_;       // [TILE_H] float32
    AscendC::TBuf<AscendC::TPosition::VECCALC> cvBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> msBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> nsBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> dsBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tdTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tfTileBuf_;
};

// =========================================================================
// dtype dispatch helper
// =========================================================================

template <template <typename> class Kernel>
__aicore__ inline void DispatchKernel(
    GM_ADDR time_decay, GM_ADDR key, GM_ADDR time_first, GM_ADDR value,
    GM_ADDR max_state, GM_ADDR num_state, GM_ADDR den_state,
    GM_ADDR output, GM_ADDR out_max_state, GM_ADDR out_num_state, GM_ADDR out_den_state,
    int32_t batchSize, int32_t seqLen, int32_t hiddenSize, int32_t tasksPerCore,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(time_decay, key, time_first, value,
                    max_state, num_state, den_state,
                    output, out_max_state, out_num_state, out_den_state,
                    batchSize, seqLen, hiddenSize, tasksPerCore);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(time_decay, key, time_first, value,
                    max_state, num_state, den_state,
                    output, out_max_state, out_num_state, out_den_state,
                    batchSize, seqLen, hiddenSize, tasksPerCore);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(time_decay, key, time_first, value,
                    max_state, num_state, den_state,
                    output, out_max_state, out_num_state, out_den_state,
                    batchSize, seqLen, hiddenSize, tasksPerCore);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void time_decay_exp_stabilization(
    GM_ADDR time_decay, GM_ADDR key, GM_ADDR time_first, GM_ADDR value,
    GM_ADDR max_state, GM_ADDR num_state, GM_ADDR den_state,
    GM_ADDR output, GM_ADDR out_max_state, GM_ADDR out_num_state, GM_ADDR out_den_state,
    int32_t batchSize, int32_t seqLen, int32_t hiddenSize, int32_t tasksPerCore,
    int64_t dtypeFlag)
{
    DispatchKernel<TimeDecayExpStabilizationKernel>(
        time_decay, key, time_first, value,
        max_state, num_state, den_state,
        output, out_max_state, out_num_state, out_den_state,
        batchSize, seqLen, hiddenSize, tasksPerCore,
        dtypeFlag);
}
